import random

# Définition des lignes de pêche
lignes_de_peche = {
    "classique": {"nom": "Ligne de pêche classique", "chance": 0.5},
    "haute-tech": {"nom": "Ligne de pêche haute-tech", "chance": 0.8}
}

# Définition des poissons
poissons = {
    "carpe": {"nom": "Carpe", "pointage": 10},
    "truite": {"nom": "Truite", "pointage": 20},
    "brochet": {"nom": "Brochet", "pointage": 30}
}

# Fonction pour attraper un poisson
def attraper_poisson(ligne_de_peche, chance):
    if random.random() < chance:
        return random.choice(list(poissons.values()))
    else:
        return None

# Fonction pour jouer au jeu
def jouer():
    print("Bienvenue dans le jeu de poisson !")
    print("Vous pouvez choisir entre deux types de lignes de pêche :")
    for i, ligne in enumerate(lignes_de_peche.values()):
        print(f"{i+1}. {ligne['nom']}")

    # Demander au joueur de choisir sa ligne de pêche
    ligne_de_peche = lignes_de_peche["classique"]
    while True:
        choix = input("Tapez le numéro de la ligne de pêche que vous voulez choisir : ")
        if choix in ["1", "2"]:
            if choix == "1":
                ligne_de_peche = lignes_de_peche["classique"]
            else:
                ligne_de_peche = lignes_de_peche["haute-tech"]
            break
        else:
            print("Veuillez choisir un numéro valide.")

    # Attraper un poisson
    poisson = attraper_poisson(ligne_de_peche, ligne_de_peche["chance"])

    # Afficher les résultats
    if poisson:
        print(f"Vous avez attrapé un {poisson['nom']} !")
        print(f"Le pointage de ce poisson est de {poisson['pointage']} points.")
    else:
        print("Vous n'avez attrapé aucun poisson.")

# Lancer le jeu
jouer()
```

